function publishRequirements(audience) {
  const requirements = {
    "personal": [],
    "trusted-friends": ["2-step-verification"],
    "16+": ["2-step-verification", "age-check"],
    "all-ages": ["2-step-verification", "age-check", "id-verification"]
  };
  const list = requirements[audience];
  if (!list) {
    throw new Error(`Unknown audience: ${audience}`);
  }
  return [...list].sort();
}
