function updateOutcome({ supervised, uptimeSec, crashed }) {
  // Without a supervisor there is nothing to roll back to, so the update is not applied.
  if (!supervised) return "not-applied";
  // A crash in the new version means it is rolled back.
  if (crashed) return "rolled-back";
  // Healthy for long enough means confirmed. The 300-second threshold is an assumed value.
  if (uptimeSec >= 300) return "confirmed";
  // Still in the probation window.
  return "pending";
}
